/**
 * FULL FLEX – Commercial Offering Migration Dashboard (Appsmith Custom Widget)
 * Vanilla JS (no build step). Two tabs:
 *   Account View       – appsmith.model.accounts (AccountMigration: active-contract accounts)
 *   Migrations-Pipeline – appsmith.model.opps    (OppMigration: Hire_2_0__c = true opps)
 *
 * Batch migration logic: accounts on an active contract are migrated in
 * quarterly batches. A batch account gets a migration-potential opp
 * (Hire_2_0__c = true) → "In Migration". Once won, the account flag
 * New_Commercial_Offering__c flips true → "Migriert". Everything else
 * active-but-unflagged is "Noch offen" (pool for future batches).
 */

var ACC_SEGMENTS = [
  { key: "migrated",    label: "Migriert",     color: "#1f9d55" },
  { key: "inMigration", label: "In Migration", color: "#e0a800" },
  { key: "open",        label: "Noch offen",   color: "#8a94a6" }
];
var PIPE_SEGMENTS = [
  { key: "open", label: "Offen",     color: "#3b82f6" },
  { key: "won",  label: "Gewonnen",  color: "#1f9d55" },
  { key: "lost", label: "Verloren",  color: "#e5484d" }
];
function segColor(segs, k) { for (var i = 0; i < segs.length; i++) if (segs[i].key === k) return segs[i].color; return "#8a94a6"; }
function segLabel(segs, k) { for (var i = 0; i < segs.length; i++) if (segs[i].key === k) return segs[i].label; return k; }

var STAGE_ORDER = ["In Discussion", "Ready for Sales", "Demo Held", "Pitch & Negotiation",
  "Offer", "Contract received", "Closed Won", "Closed Lost"];
var STAGE_COLORS = {
  "In Discussion": "#94a3b8", "Ready for Sales": "#60a5fa", "Demo Held": "#38bdf8",
  "Pitch & Negotiation": "#a78bfa", "Offer": "#f59e0b", "Contract received": "#fb923c",
  "Closed Won": "#1f9d55", "Closed Lost": "#e5484d", "Andere": "#cbd5e1"
};

var BUCKETS = [
  { key: "overdue", label: "Überfällig (CloseDate vergangen)", max: -1 },
  { key: "b30",  label: "≤ 30 Tage",     max: 30 },
  { key: "b90",  label: "31 – 90 Tage",  max: 90 },
  { key: "b180", label: "91 – 180 Tage", max: 180 },
  { key: "bmax", label: "> 180 Tage",    max: Infinity }
];

var state = {
  tab: "account",
  accGroupBy: "motion",    // motion | tl
  accHighPrioOnly: false,  // account view filter
  pipeGroupBy: "stage",    // stage | motion | tl | timeline
  pipeScope: "all",        // all | active
  hpGroupBy: "timeline",   // timeline | motion (High Priority tab)
  revTrendGran: "week",    // week | month (revenue trend)
  search: "",
  expanded: {}
};

// High Priority = accounts with a HeyPaket ending within 3 months (buckets in days).
var HP_BUCKETS = [
  { key: "h30", label: "HeyPaket-Ende ≤ 30 Tage", max: 30 },
  { key: "h60", label: "31 – 60 Tage", max: 60 },
  { key: "h90", label: "61 – 90 Tage", max: Infinity }
];

/* ---------- helpers ---------- */

function el(tag, cls, html) { var e = document.createElement(tag); if (cls) e.className = cls; if (html != null) e.innerHTML = html; return e; }
function esc(s) { return String(s == null ? "" : s).replace(/[&<>"]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]; }); }
function pct(n, d) { return d ? Math.round((n / d) * 100) : 0; }

function looksLikeRecords(arr) { if (!Array.isArray(arr) || arr.length === 0) return false; var f = arr[0]; return !!(f && typeof f === "object" && (f.attributes || f.Id || f.Name)); }
function findRecords(x, depth) {
  if (x == null || depth > 6) return null;
  if (looksLikeRecords(x)) return x;
  if (Array.isArray(x)) return null;
  if (typeof x === "object") {
    if (looksLikeRecords(x.records)) return x.records;
    for (var k in x) { if (!Object.prototype.hasOwnProperty.call(x, k)) continue; var r = findRecords(x[k], depth + 1); if (r) return r; }
  }
  return null;
}
function modelArray(key) { var m = (window.appsmith && appsmith.model) || {}; var v = m[key]; if (Array.isArray(v)) return v; return findRecords(v, 0) || []; }

var fmtEur = (function () {
  try { var f = new Intl.NumberFormat("de-DE", { style: "currency", currency: "EUR", maximumFractionDigits: 0 }); return function (n) { return f.format(n || 0); }; }
  catch (e) { return function (n) { return "€" + Math.round(n || 0); }; }
})();
function fmtDate(s) { if (!s) return "–"; var d = new Date(s); if (isNaN(d)) return esc(s); var p = function (x) { return (x < 10 ? "0" : "") + x; }; return p(d.getDate()) + "." + p(d.getMonth() + 1) + "." + d.getFullYear(); }
function daysUntil(s) { var d = new Date(s); if (isNaN(d)) return Infinity; return Math.floor((d - new Date()) / 86400000); }

function emptyCounts(segs) { var c = { total: 0, amount: 0 }; segs.forEach(function (s) { c[s.key] = 0; c[s.key + "Amt"] = 0; }); return c; }
function addTo(c, segKey, amount) { c[segKey] += 1; c.total += 1; c.amount += (amount || 0); c[segKey + "Amt"] += (amount || 0); }
function convPct(c) { var d = c.won + c.lost; return d ? Math.round((c.won / d) * 100) : null; }

function stackedBar(counts, segs) {
  var bar = el("div", "bar");
  segs.forEach(function (s) {
    var w = counts.total ? (counts[s.key] / counts.total) * 100 : 0;
    if (w > 0) { var span = el("span"); span.style.width = w + "%"; span.style.background = s.color; span.title = s.label + ": " + counts[s.key]; bar.appendChild(span); }
  });
  return bar;
}
function segLegend(counts, segs) { return segs.map(function (s) { return '<span style="color:' + s.color + '">●</span> ' + counts[s.key]; }).join("&nbsp;&nbsp;"); }

function kpiCard(labelHtml, value, sub, cls, onClick) {
  var c = el("div", "kpi" + (cls ? " " + cls : "") + (onClick ? " clickable-kpi" : ""));
  c.appendChild(el("div", "k-label", labelHtml));
  c.appendChild(el("div", "k-value", value));
  if (sub) c.appendChild(el("div", "k-sub", sub));
  if (onClick) c.addEventListener("click", onClick);
  return c;
}
function segToggle(options, current, onPick) {
  var wrap = el("div", "seg-toggle");
  options.forEach(function (o) { var b = el("button", current === o[0] ? "active" : "", o[1]); b.addEventListener("click", function () { if (current !== o[0]) onPick(o[0]); }); wrap.appendChild(b); });
  return wrap;
}
function searchBox(placeholder) {
  var search = el("div", "search");
  search.appendChild(el("span", "ico", "🔍"));
  var input = el("input"); input.type = "text"; input.placeholder = placeholder; input.value = state.search;
  input.addEventListener("input", function (e) { state.search = e.target.value; rerenderBody(); });
  search.appendChild(input);
  return search;
}
function matches(rec, q, fields) { if (!q) return true; q = q.toLowerCase(); return fields.map(function (f) { return rec[f] || ""; }).join(" ").toLowerCase().indexOf(q) !== -1; }

var NONE_MOTION = "— ohne Motion", NONE_TL = "— ohne Team Lead", NONE_IC = "— ohne Owner";

// Salesforce GTM motion -> "Adjusted GTM Area" (display + grouping).
// Note: both Enterprise motions map to "EP" and therefore merge into one group.
var MOTION_MAP = {
  "Enterprise New Business": "EP",
  "Enterprise Retention": "EP",
  "Subscription Retention": "Mid-Market ACM",
  "Subscription New Business": "Mid-Market New Business",
  "Subscription Prospecting": "Mid-Market New Business",
  "Agency Sales": "Agency",
  "Inside Sales": "SMB"
};
function mapMotion(m) { return m ? (MOTION_MAP[m] || m) : NONE_MOTION; }
// Motion/TL/IC derive from the Account OWNER (User): GTM_Motion_User__c,
// Owner.Manager (TL), Owner.Name (IC). Same owner is used on opp level.
function ownerFields(owner) {
  owner = owner || {};
  return {
    motion: mapMotion(owner.GTM_Motion_User__c),
    tl: (owner.Manager && owner.Manager.Name) || NONE_TL,
    ic: owner.Name || NONE_IC
  };
}
// Only accounts under real sales leadership (owner has a GTM motion AND a manager).
// Excludes pools / lead gen / admin owners without motion or without a TL.
function hasLeadership(x) { return x.motion !== NONE_MOTION && x.tl !== NONE_TL; }

/* ---------- data derivation ---------- */

function rawOpps() { return modelArray("opps"); }

// Accounts (active contract) that have an OPEN migration-potential opp.
function openMigrationAccountSet() {
  var s = {};
  rawOpps().forEach(function (o) { if (o && o.IsClosed === false && o.AccountId) s[o.AccountId] = true; });
  return s;
}

function currentAccounts() {
  var openMP = openMigrationAccountSet();
  var hp = highPrioIdSet();
  return modelArray("accounts").map(function (r) {
    var migrated = r.New_Commercial_Offering__c === true;
    var of = ownerFields(r.Owner);
    var h = hp[r.Id];
    return {
      id: r.Id,
      name: r.Name || "(ohne Name)",
      motion: of.motion,
      tl: of.tl,
      ic: of.ic,
      segment: migrated ? "migrated" : (openMP[r.Id] ? "inMigration" : "open"),
      highPrio: !!h,
      hpEnd: h ? h.end : null,
      hpDays: h ? h.days : null,
      hpStatus: h ? h.status : null
    };
  }).filter(hasLeadership);
}

// High Priority = accounts with a HeyPaket ending within 3 months (query HighPriority).
function currentHighPrio() {
  var openMP = openMigrationAccountSet();
  var m = {};
  modelArray("highPrio").forEach(function (o) {
    var accId = o.AccountId; if (!accId) return;
    var acc = o.Account || {};
    var of = ownerFields(acc.Owner);
    if (!hasLeadership(of)) return;
    var end = o.HeyPaket_End_Date__c;
    var ex = m[accId];
    if (!ex || (end && (!ex.end || end < ex.end))) {
      var migrated = acc.New_Commercial_Offering__c === true;
      m[accId] = {
        id: accId, name: acc.Name || "(ohne Account)",
        motion: of.motion, tl: of.tl, ic: of.ic,
        segment: migrated ? "migrated" : (openMP[accId] ? "inMigration" : "open"),
        end: end, days: daysUntil(end), status: o.HeyPaket_Status__c, type: o.HeyPaket_Type__c
      };
    }
  });
  return Object.keys(m).map(function (k) { return m[k]; });
}
function highPrioIdSet() { var s = {}; currentHighPrio().forEach(function (a) { s[a.id] = a; }); return s; }

function currentOpps() {
  var activeSet = {};
  modelArray("accounts").forEach(function (a) { activeSet[a.Id] = true; });
  return rawOpps().map(function (o) {
    var acc = o.Account || {};
    var of = ownerFields(acc.Owner);
    var status = !o.IsClosed ? "open" : (o.IsWon ? "won" : "lost");
    return {
      id: o.Id,
      created: o.CreatedDate,
      account: acc.Name || "(ohne Account)",
      name: o.Name || "(ohne Name)",
      motion: of.motion,
      tl: of.tl,
      ic: of.ic,
      stage: o.StageName || "(ohne Stage)",
      status: status,
      segment: status,
      close: o.CloseDate,
      days: daysUntil(o.CloseDate),
      amount: o.Amount || 0,
      reach: o.Monthly_Reach_Budget__c,
      product: o.Product_Type__c,
      type: o.Contract_type__c,
      activity: o.LastActivityDate,
      accMigrated: acc.New_Commercial_Offering__c === true,
      inActive: !!activeSet[o.AccountId]
    };
  }).filter(hasLeadership);
}

/* ---------- generic tree ---------- */

function buildTree(items, keys, segs) {
  var root = { counts: emptyCounts(segs), children: {}, _order: [] };
  items.forEach(function (it) {
    addTo(root.counts, it.segment, it.amount || 0);
    var node = root;
    for (var i = 0; i < keys.length; i++) {
      var k = it[keys[i]];
