  if (accs.length === 0) {
    var e = el("div", "empty");
    e.innerHTML = "<h3>Noch keine High-Priority-Daten verbunden</h3><p>Erwartet <code>appsmith.model.highPrio</code> aus der Query <code>HighPriority</code> (HeyPaket-Ende ≤ 3 Monate, Status ≠ Inactive).</p>";
    container.appendChild(e); return;
  }
  var counts = emptyCounts(ACC_SEGMENTS);
  accs.forEach(function (a) { addTo(counts, a.segment, 0); });

  var kpis = el("div", "kpis");
  kpis.appendChild(kpiCard("High-Priority Accounts", String(accs.length), "HeyPaket-Ende ≤ 3 Monate", "total"));
  ACC_SEGMENTS.forEach(function (s) {
    kpis.appendChild(kpiCard('<span class="dot" style="background:' + s.color + '"></span>' + s.label,
      String(counts[s.key]), pct(counts[s.key], accs.length) + "% der High-Prio"));
  });
  container.appendChild(kpis);

  var controls = el("div", "controls");
  controls.appendChild(segToggle([["timeline", "Nach HeyPaket-Ende"], ["motion", "Nach Motion"]], state.hpGroupBy, function (v) { state.hpGroupBy = v; state.expanded = {}; render(); }));
  controls.appendChild(searchBox("Account, Motion, TL, IC suchen…"));
  container.appendChild(controls);

  var body = el("div"); body.id = "view-body"; container.appendChild(body);
  renderHighPrioBody(body, accs);
}
function renderHighPrioBody(body, accs) {
