  var filtered = accs.filter(function (a) { return matches(a, state.search, ["name", "motion", "tl", "ic"]); });
  var treeEl = el("div", "tree");
  var head = el("div", "thead");
  head.appendChild(el("div", "", state.hpGroupBy === "timeline" ? "HeyPaket-Ende / Account" : "Motion / Team Lead / IC"));
  head.appendChild(el("div", "num", "Accounts"));
