    var groups = HP_BUCKETS.map(function (b) { return { bucket: b, counts: emptyCounts(ACC_SEGMENTS), items: [] }; });
    filtered.forEach(function (a) { for (var i = 0; i < HP_BUCKETS.length; i++) { if (a.days <= HP_BUCKETS[i].max) { addTo(groups[i].counts, a.segment, 0); groups[i].items.push(a); break; } } });
